import json,re,urllib.error,urllib.request
run='run_mvrnydib_f5e96251e5'
for route in ('status','inspect'):
    url='http://127.0.0.1:8787/v1/'+route+'/'+run
    try:
        with urllib.request.urlopen(url,timeout=5) as response:
            status=response.status
            payload=json.loads(response.read(32768))
    except urllib.error.HTTPError as e:
        status=e.code
        try: payload=json.loads(e.read(32768))
        except (ValueError,TypeError): payload={}
    except (TimeoutError,OSError):
        status=0;payload={}
    code=str(payload.get('code','UNKNOWN')) if isinstance(payload,dict) else 'UNKNOWN'
    if not re.fullmatch(r'[A-Z0-9_.:-]{1,100}',code): code='REDACTED_OR_UNKNOWN'
    print(route.upper()+'_HTTP='+str(status))
    print(route.upper()+'_ERROR_CLASS='+code)
PY
